UPDATE dependency_metric_alert_delivery SET status=#{status}, error_message=#{errorMessage},
  completed_at=CASE WHEN #{status} IN ('SUCCESS','FAILED','SKIPPED') THEN NOW() ELSE completed_at END
WHERE alert_date=#{alertDate}
